/// The operations of group boolean. A kernel that misses a method does not analyze.
abstract interface class BooleanKernel {
  /// The negation.
  bool not(bool value);
}

/// The operations of group bytes. A kernel that misses a method does not analyze.
abstract interface class BytesKernel {
  /// The bytes of integers from 0 to 255.
  ByteString fromList(List<int> values);

  /// The bytes as integers from 0 to 255.
  List<int> toList(ByteString value);
}

/// The operations of group catalog. A kernel that misses a method does not analyze.
abstract interface class CatalogKernel {
  /// The published declaration of the type a selection names; missing at no
  /// location when the catalog lacks it. Panel profile.
  PortableMaybe<_lib_editor_v1_type_catalog.DataValue> declaration(
    _lib_editor_v1_type_catalog.DataValue selection,
    PortableResources resources,
  );
}

/// The operations of group collection. A kernel that misses a method does not analyze.
abstract interface class CollectionKernel {
  /// Whether an item equals value. Stops at the first hit.
  bool contains(
    List<_lib_editor_v1_type_catalog.ListItem> source,
    _lib_editor_v1_type_catalog.DataValue value,
  );

  /// The items whose predicate is true, keeping their identities.
  List<_lib_editor_v1_type_catalog.ListItem> filter(
    List<_lib_editor_v1_type_catalog.ListItem> source,
    List<bool> predicate,
  );

  /// Folds the items from initial, left to right.
  _lib_editor_v1_type_catalog.DataValue fold(
    List<_lib_editor_v1_type_catalog.ListItem> source,
    _lib_editor_v1_type_catalog.DataValue initial,
    PortableStep step,
  );

  /// The items grouped by key, in order of first occurrence.
  List<_lib_editor_v1_type_catalog.MapRow> groupBy(
    List<_lib_editor_v1_type_catalog.ListItem> source,
    List<_lib_editor_v1_type_catalog.DataValue> key,
  );

  /// The body's result for every item, keeping the item identities.
  List<_lib_editor_v1_type_catalog.ListItem> map(
    List<_lib_editor_v1_type_catalog.ListItem> source,
    List<_lib_editor_v1_type_catalog.DataValue> body,
  );

  /// The number of items, including unfilled ones.
  int size(List<_lib_editor_v1_type_catalog.ListItem> source);

  /// The items ordered by key; equal keys keep their order.
  List<_lib_editor_v1_type_catalog.ListItem> sortBy(
    List<_lib_editor_v1_type_catalog.ListItem> source,
    List<_lib_editor_v1_type_catalog.DataValue> key,
    SortDirection direction,
  );

  /// The items ordered by comparator; equal items keep their order.
  List<_lib_editor_v1_type_catalog.ListItem> sortWith(
    List<_lib_editor_v1_type_catalog.ListItem> source,
    PortableComparator comparator,
    PortableMeter meter,
  );

  /// The items as a list.
  List<_lib_editor_v1_type_catalog.ListItem> toList(
