  );

  /// The value as the numeric type M when it is exactly representable there.
  PortableNumber convert(
    PortableNumber value,
    _lib_editor_v1_type_catalog.TypeUse mType,
  );

  /// The quotient. Integers truncate toward zero; decimals round to 34
  /// significant digits, half even; floats follow IEEE 754.
  PortableNumber divide(PortableNumber dividend, PortableNumber divisor);

  /// The value with exactly fraction_digits fraction digits (rounded half even; a
  /// float from its shortest round trip decimal) and the locale's CLDR digits,
  /// grouping and symbols. Locale und uses no grouping. More than 20000 fraction
  /// digits, or a result of more than 20000 digits, fails magnitude_limit. Panel
  /// profile.
  String format(PortableNumber value, int fractionDigits, String locale);

  /// The product.
  PortableNumber multiply(
    PortableNumber first,
    PortableNumber second,
    List<PortableNumber> rest,
  );

  /// The CLDR plural category of the value in the locale, from the plural
  /// operands of its exact decimal value (a float through its shortest round trip
  /// decimal). A magnitude of 10^21 or more, or more than 20 fraction digits, is
  /// beyond the platform plural rules and fails magnitude_limit. Panel profile.
  PluralCategory pluralCategory(PortableNumber value, String locale);

  /// Value raised to a nonnegative integer exponent, where any value to the power
  /// 0 is 1; exact for integers and decimals.
  PortableNumber power(PortableNumber value, int exponent);

  /// The remainder of truncating division; it has the sign of the dividend.
  PortableNumber remainder(PortableNumber dividend, PortableNumber divisor);

  /// Rounds value to a multiple of increment.
  PortableNumber round(
    PortableNumber value,
    PortableNumber increment,
    RoundingMode mode,
  );

  /// The square root. Integers round down; decimals round to 34 significant
  /// digits, half even; floats follow IEEE 754.
  PortableNumber sqrt(PortableNumber value);

  /// The difference.
  PortableNumber subtract(PortableNumber first, PortableNumber second);
