  /// PT1M30.5S.
  Duration parseDuration(String value);

  /// Parses an optionally signed finite floating point number in plain or
  /// exponent notation.
  double parseFloat(String value);

  /// Parses an optionally signed integer of digits in radix. No whitespace or
  /// prefixes.
  BigInt parseInteger(String value, int radix);

  /// Parses an RFC 3339 timestamp.
  DateTime parseTimestamp(String value);

